PYTHON_LOCK = (
    "# This file was autogenerated by uv via the following command:\n"
    "# uv pip compile requirements.in --generate-hashes -o requirements.lock\n"
    "applemusic-mcp==0.20.0 \\\n"
    "    --hash=sha256:" + "a" * 64 + " \\\n"
    "    --hash=sha256:" + "b" * 64 + "\n"
).encode("utf-8")


def npm_lock(resolved: str = "https://registry.npmjs.org/example-mcp/-/example-mcp-1.2.3.tgz") -> bytes:
    return (json.dumps({
        "name": "custom-node-wrapper",
        "version": "1.0.0",
        "lockfileVersion": 3,
        "packages": {
            "": {
                "name": "custom-node-wrapper",
                "version": "1.0.0",
                "dependencies": {"example-mcp": "^1.2.0"},
            },
            "node_modules/example-mcp": {
                "version": "1.2.3",
                "resolved": resolved,
                "integrity": "sha512-" + base64.b64encode(b"i" * 64).decode("ascii"),
            },
        },
    }, sort_keys=True) + "\n").encode("utf-8")


def local_item(recipe_type: str) -> dict:
    common_fields = {
        "id": f"default-{recipe_type}",
        "server": recipe_type,
        "profile": "default",
        "archivePrefix": f"local-mcp-projects/default-{recipe_type}/content",
        "target": {
            "kind": "home",
            "relativePath": f".local/share/{recipe_type}",
            "requiresExplicitMapping": False,
        },
        "argsPathRewrites": [],
        "envPathRewrites": [],
        "reauthorizationRequired": True,
        "portableState": [],
        "excludedAccountState": [],
    }
    if recipe_type == "python-uv-lock":
        common_fields.update({
            "commandRelativePath": ".runtime/bin/python",
            "argsTemplate": ["-m", "applemusic_readonly_mcp.server"],
            "runtimeRecipe": {
                "type": "python-uv-lock",
                "python": "3.11",
                "runtimeRelativePath": ".runtime",
                "lockFile": "requirements.lock",
                "installLocalPackage": True,
                "verification": {
                    "type": "python-import",
                    "module": "applemusic_readonly_mcp.server",
                },
            },
        })
    else:
        common_fields.update({
            "commandName": "node",
            "argsTemplate": ["C:/source/node_modules/example-mcp/index.js"],
            "argsPathRewrites": [{
                "index": 0,
                "relativePath": "node_modules/example-mcp/index.js",
            }],
            "runtimeRecipe": {
                "type": "node-npm-lock",
                "lockFile": "package-lock.json",
                "installMode": "npm-ci-ignore-scripts",
                "verification": {"type": "node-check", "argIndex": 0},
            },
        })
    return common_fields


def manifest_with(item: dict, lock_bytes: bytes) -> dict:
    item = copy.deepcopy(item)
    item["installation"] = common.build_local_mcp_installation(item, lock_bytes)
    lock_rel = f"{item['archivePrefix']}/{item['runtimeRecipe']['lockFile']}"
    return {
        "schemaVersion": "2.2",
        "options": {"profile": "basic"},
        "entries": [{
            "relPath": lock_rel,
            "sha256": hashlib.sha256(lock_bytes).hexdigest(),
            "artifactClass": "local-mcp-source",
        }],
        "externalRoots": [],
        "links": [],
        "softwareInventory": [],
        "projectMappings": [],
        "postRestoreActions": [],
        "coverageGaps": [],
        "providerSources": [],
        "localMcpProjects": [item],
    }


class LocalMcpInstallationTests(unittest.TestCase):
    def test_live_json_is_frozen_at_finalize_and_preflight_uses_payload(self):
        with tempfile.TemporaryDirectory() as tmp:
            source = Path(tmp) / "jobs.json"
            source.write_text('{"revision":1}\n', encoding="utf-8")
            manifest = {
                "options": {}, "desktopConsistency": {}, "sanitized": [],
                "keptSecrets": [], "entries": [{
                    "relPath": "hermes/cron/jobs.json", "originPath": str(source),
                    "sha256": hashlib.sha256(source.read_bytes()).hexdigest(),
                    "size": source.stat().st_size, "type": "automation",
                    "artifactClass": "automation", "linkTarget": None,
                }],
            }
            source.write_text('{"revision":2}\n', encoding="utf-8")
            collector = SimpleNamespace(m=manifest, include_secrets=False)
            backup.prepare_live_json_snapshots(collector)
            entry = manifest["entries"][0]
            self.assertEqual(json.loads(entry["_payload"]), {"revision": 2})
            self.assertEqual(entry["snapshotMethod"], "finalize-json-point-in-time")
            source.write_text('{"revision":3}\n', encoding="utf-8")
            backup.preflight_sources(manifest)

