    def test_fresh_checks_desktop_provider_external_and_project_targets(self):
        with tempfile.TemporaryDirectory() as tmp:
            home = Path(tmp) / "home"
            hermes = home / "AppData" / "Local" / "hermes"
            desktop = common.hermes_desktop_home_for_user(home, "windows")
            (desktop / "occupied").mkdir(parents=True)
            (desktop / "occupied" / "file").write_text("x", encoding="utf-8")
            provider = hermes / "plugins" / "memory"
            provider.mkdir(parents=True)
            (provider / "provider.py").write_text("x", encoding="utf-8")
            external = home / "external"
            project = home / "project"
            external.mkdir(parents=True)
            project.mkdir(parents=True)
            manifest = {
                "localMcpProjects": [],
                "externalRoots": [{
                    "id": "root-x", "targetTemplate": None,
                    "requiresExplicitMapping": True,
                }],
                "projectMappings": [{"id": "project-x"}],
            }
            state = restore.detect_fresh(
                home, hermes, manifest, {}, "windows",
                {"project-x": project}, {"root-x": external},
            )
            for part in ("hermes-desktop", "hermes-provider", "external-roots", "projects"):
                self.assertFalse(state[part]["fresh"], part)

            mac_home = Path(tmp) / "mac-home"
            mac_hermes = mac_home / ".hermes"
            mac_desktop = common.hermes_desktop_home_for_user(mac_home, "macos")
            mac_desktop.mkdir(parents=True)
            (mac_desktop / "occupied").write_text("x", encoding="utf-8")
            mac_state = restore.detect_fresh(
                mac_home, mac_hermes, {"localMcpProjects": [], "externalRoots": [],
                                      "projectMappings": []}, {}, "macos", {}, {},
            )
            self.assertFalse(mac_state["hermes-desktop"]["fresh"])

    def test_ms365_launch_suffix_is_bound_to_audited_package_and_version(self) -> None:
        item = {
            "argsTemplate": [
                "C:/source/node_modules/@softeria/ms-365-mcp-server/dist/index.js",
                "--preset", "mail,calendar",
            ],
            "argsPathRewrites": [{
                "index": 0,
                "relativePath": "node_modules/@softeria/ms-365-mcp-server/dist/index.js",
            }],
            "runtimeRecipe": {
                "type": "node-npm-lock",
                "verification": {"argIndex": 0},
            },
            "installation": {"packageProvenance": [{
                "package": "@softeria/ms-365-mcp-server",
                "version": "0.145.2",
            }]},
        }
        self.assertTrue(common.node_item_has_trusted_launch_args(item))
        rebuilt = restore._typed_local_mcp_args(item, Path("C:/target/ms365"))
        self.assertEqual(rebuilt[-2:], ["--preset", "mail,calendar"])
        item["argsTemplate"][-1] = "mail,calendar,files"
        self.assertFalse(common.node_item_has_trusted_launch_args(item))
        item["argsTemplate"][-1] = "mail,calendar"
        item["installation"]["packageProvenance"][0]["version"] = "0.145.3"
        self.assertFalse(common.node_item_has_trusted_launch_args(item))

    def test_python_custom_wrapper_keeps_embedded_source_and_only_pin_hash_evidence(self) -> None:
        manifest = manifest_with(local_item("python-uv-lock"), PYTHON_LOCK)
        installation = manifest["localMcpProjects"][0]["installation"]
        self.assertIsNone(installation["trustedSource"])
        self.assertEqual(installation["runtime"], {
            "name": "python", "version": "3.11", "packageManager": "uv",
            "recipeType": "python-uv-lock",
        })
        self.assertEqual(installation["embeddedSourceFallback"]["role"], "custom-project-source")
        self.assertEqual(installation["packageProvenance"], [{
            "type": "pypi-locked-requirement",
            "package": "applemusic-mcp",
            "version": "0.20.0",
            "hashes": ["sha256:" + "a" * 64, "sha256:" + "b" * 64],
            "role": "locked-dependency",
        }])
        self.assertNotIn("repository", json.dumps(installation))
        self.assertNotIn("resolved", json.dumps(installation))
        restore.validate_manifest(manifest)

