    def test_sec001_python_lock_rejects_all_installer_directives(self) -> None:
        directives = (
            "--index-url=https://evil.invalid/simple",
            "--extra-index-url https://evil.invalid/simple",
            "--find-links=https://evil.invalid/wheels",
            "--trusted-host evil.invalid",
            "--constraint=constraints.txt",
        )
        for directive in directives:
            with self.subTest(directive=directive):
                hostile = directive.encode() + b"\n" + PYTHON_LOCK
                self.assertIsNone(common.parse_hash_locked_requirements(hostile))
                with self.assertRaisesRegex(ValueError, "hash-locked"):
                    common.build_local_mcp_installation(
                        local_item("python-uv-lock"), hostile
                    )

        embedded = PYTHON_LOCK.replace(
            b"--hash=sha256:" + b"a" * 64,
            b"--hash=sha256:" + b"a" * 64 + b" --index-url=https://evil.invalid/simple",
        )
        self.assertIsNone(common.parse_hash_locked_requirements(embedded))

    def test_sec002_unsafe_or_unverified_npm_resolution_fails_closed(self) -> None:
        for url in (
            "http://registry.npmjs.org/example-mcp/-/example-mcp-1.2.3.tgz",
            "https://example.invalid/example-mcp-1.2.3.tgz",
            "file:///tmp/example-mcp.tgz",
        ):
            with self.subTest(url=url):
                with self.assertRaisesRegex(ValueError, "supported package lock"):
                    common.build_local_mcp_installation(
                        local_item("node-npm-lock"), npm_lock(url)
                    )

        missing_integrity = json.loads(npm_lock().decode())
        del missing_integrity["packages"]["node_modules/example-mcp"]["integrity"]
        linked = json.loads(npm_lock().decode())
        linked["packages"]["node_modules/example-mcp"] = {
            "resolved": "src/example-mcp", "link": True,
        }
        transitive_http = json.loads(npm_lock().decode())
        transitive_http["packages"]["node_modules/example-mcp"]["dependencies"] = {"child": "1.0.0"}
        transitive_http["packages"]["node_modules/child"] = {
            "version": "1.0.0",
            "resolved": "http://registry.npmjs.org/child/-/child-1.0.0.tgz",
            "integrity": "sha512-" + base64.b64encode(b"c" * 64).decode("ascii"),
        }
        for hostile in (missing_integrity, linked, transitive_http):
            with self.assertRaisesRegex(ValueError, "supported package lock"):
                common.build_local_mcp_installation(
                    local_item("node-npm-lock"),
                    (json.dumps(hostile) + "\n").encode(),
                )

