    def test_embedded_lock_is_rederived_and_tampering_is_rejected(self) -> None:
        lock_bytes = npm_lock()
        manifest = manifest_with(local_item("node-npm-lock"), lock_bytes)
        with tempfile.TemporaryDirectory() as raw:
            root = Path(raw)
            item = manifest["localMcpProjects"][0]
            lock_path = root / Path(item["archivePrefix"]) / "package-lock.json"
            lock_path.parent.mkdir(parents=True)
            lock_path.write_bytes(lock_bytes)
            reader = restore.BackupReader(str(root), None)
            try:
                restore.validate_installation_evidence(reader, manifest)
                tampered = copy.deepcopy(manifest)
                tampered["localMcpProjects"][0]["installation"]["lock"]["sha256"] = "0" * 64
                with self.assertRaises(SystemExit):
                    restore.validate_installation_evidence(reader, tampered)
            finally:
                reader.close()

