    def test_sec006_backup_collector_rejects_local_mcp_file_symlink(self) -> None:
        class FakeCollector:
            def __init__(self) -> None:
                self.m = {"entries": [], "coverageGaps": [], "excluded": []}

            def record_excluded(self, path: Path, reason: str) -> None:
                self.m["excluded"].append({"originPath": str(path), "reason": reason})

            def collect_file(self, *_args, **_kwargs) -> None:
                raise AssertionError("local MCP symlink reached collect_file")

        with tempfile.TemporaryDirectory() as raw:
            root = Path(raw)
            linked = root / "src" / "linked.py"
            linked.parent.mkdir()
            linked.write_text("placeholder\n", encoding="utf-8")
            collector = FakeCollector()
            with mock.patch.object(common, "is_link_like", side_effect=lambda path: path == linked):
                backup._collect_local_mcp_tree(collector, root, "local-mcp-projects/x/content", 0)
            self.assertEqual(
                collector.m["coverageGaps"][0]["class"], "local-mcp-link-unresolved"
            )
            self.assertEqual(
                collector.m["excluded"][0]["reason"], "local-mcp-link-not-portable"
            )

